from flask import Flask, render_template_string, request

app = Flask(__name__)

@app.route("/td")
def time_door():
    name = request.args.get('name')
    time = request.args.get('time')

    page = """
    <h1>{}</h1>
    <h1>{}</h1>
    """.format(name, time)

    return render_template_string(page)

if __name__ == "__main__":
  app.run()
